## Validation de Données

**Checks de cohérence :**
```javascript
function validateTrackingData(data, source) {
  var issues = [];

  if (!data) {
    issues.push('Données nulles');
    return issues;
  }

  // Validation selon la source
  switch (source) {
    case 'STEP7':
      if (!data.metadata) issues.push('Metadata manquante');
      if (!data.dataByFrame) issues.push('dataByFrame manquant');
      break;

    case 'STEP6':
    case 'STEP5':
      if (!data.tracking) issues.push('Tracking data manquante');
      if (!Array.isArray(data.tracking)) issues.push('Tracking n\'est pas un array');
      break;
  }

  // Validation temporelle
  if (data.metadata && data.metadata.total_frames) {
    var expectedFrames = data.metadata.total_frames;
    var actualFrames = Object.keys(data.dataByFrame || {}).length;

    if (actualFrames < expectedFrames * 0.8) {
      issues.push('Couverture temporelle insuffisante: ' + actualFrames + '/' + expectedFrames);
    }
  }

  // Validation des visages
  if (data.dataByFrame) {
    var faceCount = 0;
    for (var frameKey in data.dataByFrame) {
      faceCount += data.dataByFrame[frameKey].length;
    }

    if (faceCount === 0) {
      issues.push('Aucun visage détecté');
    }
  }

  return issues;
}
```

## Gestion des Ponts Python

**Fallbacks pour system.callSystem() :**
```javascript
function callPythonBridge(command, timeout) {
  timeout = timeout || 30000; // 30 secondes par défaut

  try {
    var startTime = new Date().getTime();
    var result = system.callSystem(command);
    var endTime = new Date().getTime();

    // Vérifier timeout
    if (endTime - startTime > timeout) {
      $.writeln('[TIMEOUT] Python bridge exceeded ' + timeout + 'ms');
      return { success: false, error: 'timeout', timeout: true };
    }

    // Vérifier résultat
    if (result.indexOf('ERROR') !== -1 || result.indexOf('Traceback') !== -1) {
      return { success: false, error: result, python_error: true };
    }

    return { success: true, result: result };

  } catch (systemError) {
    $.writeln('[SYSTEM ERROR] callSystem failed: ' + systemError.message);
    return { success: false, error: systemError.message, system_error: true };
  }
}

function callPythonWithFallback(primaryCommand, fallbackCommand) {
  var result = callPythonBridge(primaryCommand);

  if (!result.success) {
    $.writeln('[FALLBACK] Primary failed, trying fallback...');
    result = callPythonBridge(fallbackCommand);
  }

  if (!result.success) {
    $.writeln('[CRITICAL] Both Python calls failed');
    // Continuer avec logique ExtendScript pure
    return executeExtendScriptFallback();
  }

  return result;
}
```

