function createErrorReport(comp, issues) {
  var reportLayer = comp.layers.addText('Error Report');
  var textProp = reportLayer.property('Source Text');

  var report = 'RAPPORT D\'ERREURS\n================\n\n';
  report += 'Timestamp: ' + new Date().toISOString() + '\n';
  report += 'Issues trouvés: ' + issues.length + '\n\n';

  for (var i = 0; i < issues.length; i++) {
    report += (i + 1) + '. ' + issues[i] + '\n';
  }

  var textDoc = textProp.value;
  textDoc.text = report;
  textDoc.fontSize = 24;
  textDoc.fillColor = [1, 0, 0]; // Rouge pour erreurs
  textProp.setValue(textDoc);

  return reportLayer;
}
