**Tentatives de réparation :**
```javascript
function attemptRecovery(comp, errorType, context) {
  switch (errorType) {
    case 'memory':
      // Réduire la qualité
      app.preferences.setPrefAsLong('Main Pref Section v2', 'memory', 0);
      return true;

    case 'file_missing':
      // Chercher fichiers alternatifs
      return findAlternativeFiles(context);

    case 'parsing':
      // Essayer parsing partiel
      return attemptPartialParsing(context);

    case 'python_bridge':
      // Reconfiguration PYTHON_EXECUTABLE
      return reconfigurePythonPath();

    default:
      return false;
  }
}
